function rankWord(w){const n=w.en.length;if(w.type==='basic')return n<=5?'elementary':n<=7?'middle':'high';if(['root','irregular'].includes(w.type))return'advanced';if(w.type==='phrase')return n<=8?'high':n<=10?'intermediate':'advanced';if(['prefix','suffix'].includes(w.type))return n<=5?'high':'intermediate';return n<=5?'middle':n<=7?'high':n<=9?'intermediate':'advanced'}
const WORDS=[...BASE_WORDS,...EXTRA_WORDS].map((w,i)=>({...w,id:i,answers:w.answers||w.ko.split('|'),difficulty:rankWord(w)}));
const EASY_WORDS=WORDS.filter(w=>w.difficulty==='elementary');
const DIFFICULTY={elementary:{label:'초등',speed:24,interval:2.55},middle:{label:'중등',speed:28,interval:2.35},high:{label:'고등',speed:32,interval:2.15},intermediate:{label:'중급',speed:37,interval:1.95},advanced:{label:'고급',speed:42,interval:1.75}};
const TYPE_LABEL={basic:'기본',noun:'명사',verb:'동사',adj:'형용사',adv:'부사',phrase:'표현',prefix:'접두사',suffix:'접미사',root:'어근',irregular:'불규칙'};

const $=s=>document.querySelector(s);const screens=['startScreen','gameScreen','resultScreen'];
const els={start:$('#startBtn'),retry:$('#retryBtn'),save:$('#saveImageBtn'),home:$('#homeBtn'),pause:$('#pauseBtn'),resume:$('#resumeBtn'),quit:$('#quitBtn'),modal:$('#pauseModal'),field:$('#playfield'),layer:$('#wordLayer'),form:$('#answerForm'),input:$('#answer'),score:$('#score'),combo:$('#combo'),level:$('#level'),levelGauge:$('#levelGauge'),gaugeValue:$('#gaugeValue'),feedback:$('#feedback'),comboBurst:$('#comboBurst'),levelUp:$('#levelUp'),resultBadge:$('#resultBadge'),ground:$('.ground'),deadline:$('.dead-line')};
let state,raf,lastTime,spawnClock,selectedMode='elementary';
// 단어는 화면 높이와 상관없이 같은 시간 동안 떨어짐 (p: 0=맨 위, 1=바닥). 키보드로 화면이 줄어도 단어가 한꺼번에 놓침 처리되지 않음
const TOP=-52,FALL=400;
// 시간이 지날수록 단어가 더 자주 나옴 (낙하 속도는 그대로)
function spawnInterval(){return DIFFICULTY[selectedMode].interval*.85*(1-Math.min(.3,state.elapsed/300))}
// 바닥 높이도 화면 크기에 대한 비율로 기억했다가, 화면이 바뀌면 다시 계산
function maxRise(){return Math.max(0,els.field.clientHeight-els.ground.offsetHeight-els.deadline.offsetTop)}
function applyGroundRise(){const px=Math.round(maxRise()*state.riseFrac);if(px!==state.groundRise){state.groundRise=px;els.field.style.setProperty('--ground-rise',px+'px')}}
// 화면 크기별 난이도: 단어가 떨어지는 공간이 짧으면 동시에 나오는 단어 수를 줄임
function maxWords(){const h=els.field.clientHeight-state.groundRise;return h<280?3:h<400?4:5}
// 단어가 겹치지 않게 화면을 세로 칸으로 나누고, 위쪽에 아직 단어가 있는 칸은 피해서 떨어뜨림
function pickLane(wordW){const W=els.field.clientWidth-16,lanes=Math.max(2,Math.floor(W/120)),laneW=W/lanes;const busy=new Set(state.active.filter(w=>w.p<.4).map(w=>w.lane));const all=[...Array(lanes).keys()],free=all.filter(i=>!busy.has(i)),pool=free.length?free:all;const lane=pool[Math.floor(Math.random()*pool.length)];const x=8+lane*laneW+Math.random()*Math.max(0,laneW-wordW);return{lane,x:Math.max(8,Math.min(x,W+8-wordW))}}
function show(id){screens.forEach(x=>$('#'+x).classList.toggle('active',x===id))}
function getPool(){return WORDS.filter(w=>w.difficulty===selectedMode)}
function reset(){const pool=getPool();state={score:0,combo:0,maxCombo:0,correct:0,missed:[],active:[],pool,deck:[...pool].sort(()=>Math.random()-.5),running:true,paused:false,ending:false,elapsed:0,level:1,pressure:0,lastCorrectAt:0,groundRise:0,riseFrac:0};els.layer.innerHTML='';els.field.classList.remove('hit','ground-impact','deadline-hit');els.field.style.setProperty('--ground-rise','0px');spawnClock=0;lastTime=performance.now();updateHud()}
function start(){lockPortrait();reset();show('gameScreen');spawn();els.input.value='';setTimeout(()=>els.input.focus(),120);cancelAnimationFrame(raf);raf=requestAnimationFrame(loop)}
function spawn(){if(!state.deck.length)state.deck=[...state.pool].sort(()=>Math.random()-.5);const word=state.deck.pop(),node=document.createElement('div');node.className='word';node.textContent=word.en;els.layer.appendChild(node);const {lane,x}=pickLane(node.offsetWidth),base=DIFFICULTY[selectedMode].speed;const item={...word,node,x,lane,p:0,speed:base+Math.random()*7};state.active.push(item);node.style.transform=`translate(${x}px,${TOP}px)`}
function showLevelUp(){els.levelUp.querySelector('span').textContent=state.level;els.levelUp.classList.remove('show');void els.levelUp.offsetWidth;els.levelUp.classList.add('show');navigator.vibrate?.([25,35,55])}
function addPressure(amount){if(!state?.running||state.ending)return;state.pressure=Math.max(0,state.pressure+amount);while(state.pressure>=100&&state.level<7){state.pressure-=100;state.level++;state.riseFrac=(state.level-1)/6;applyGroundRise();els.field.classList.remove('ground-impact');void els.field.offsetWidth;els.field.classList.add('ground-impact');showLevelUp();if(state.level>=7){state.ending=true;els.field.classList.add('deadline-hit');flash('DEAD LINE!','#ff5171');navigator.vibrate?.([70,35,70,35,120]);setTimeout(end,850);break}}updateGauge()}
function updateGauge(){const value=Math.round(Math.max(0,Math.min(100,state.pressure)));els.levelGauge.style.transform=`scaleX(${value/100})`;els.gaugeValue.textContent=value+'%';els.levelGauge.classList.toggle('hot',value>=72)}
function loop(now){if(!state?.running)return;const dt=Math.min((now-lastTime)/1000,.05);lastTime=now;if(!state.paused&&!state.ending){state.elapsed+=dt;spawnClock+=dt;const drought=Math.max(0,state.elapsed-state.lastCorrectAt);addPressure(dt*(1.15+Math.min(3.1,drought*.11)+state.active.length*.12));if(state.ending){raf=requestAnimationFrame(loop);return}applyGroundRise();const interval=spawnInterval();if(spawnClock>=interval&&state.active.length<maxWords()){spawnClock=0;spawn()}const floor=els.field.clientHeight-els.ground.offsetHeight-48,dist=Math.max(1,floor-TOP),limit=floor-state.groundRise;for(let i=state.active.length-1;i>=0;i--){const w=state.active[i];w.p+=w.speed*dt/FALL;const y=TOP+w.p*dist;w.y=y;w.node.style.transform=`translate(${w.x}px,${y}px)`;w.node.classList.toggle('danger',y>=limit-95);if(y>=limit)miss(i)}}raf=requestAnimationFrame(loop)}
function norm(v){return v.trim().replace(/\s+/g,'').replace(/[.!?]/g,'')}
function answer(e){e.preventDefault();if(!state?.running||state.paused||state.ending)return;const value=norm(els.input.value);if(!value)return;let idx=state.active.findIndex(w=>w.answers.some(a=>norm(a)===value));if(idx<0){state.combo=0;if(state.active.length)crack(state.active[Math.floor(Math.random()*state.active.length)]);else flash('다시 생각해봐요','#ef5b61');navigator.vibrate?.(40)}else{const w=state.active[idx];state.active.splice(idx,1);w.node.classList.add('correct-pop');setTimeout(()=>w.node.remove(),190);state.combo++;state.maxCombo=Math.max(state.maxCombo,state.combo);state.correct++;state.lastCorrectAt=state.elapsed;state.pressure=Math.max(0,state.pressure-(15+Math.min(8,state.combo)));updateGauge();const mult=1+(state.level-1)*.25,gain=Math.round((100+Math.min(400,(state.combo-1)*20))*mult);state.score+=gain;els.field.classList.remove('hit');void els.field.offsetWidth;els.field.classList.add('hit');els.comboBurst.textContent=state.combo>1?`${state.combo} COMBO!`:`+${gain}`;els.comboBurst.classList.remove('show');void els.comboBurst.offsetWidth;els.comboBurst.classList.add('show');flash(`위험 DOWN · +${gain}`,'#57d7d9');navigator.vibrate?.(state.combo>=5?[18,22,28]:18)}els.input.value='';keepTyping();updateHud()}
function miss(i){const [w]=state.active.splice(i,1);groundImpact(w);w.node.remove();state.missed.push(w);state.combo=0;addPressure(34);flash(`${w.en} = ${w.answers[0]} · 위험 UP`,'#ef5b61');navigator.vibrate?.([60,25,90]);updateHud()}
// 바닥 타격감: 단어가 찌그러지며 부서지고, 파편이 튀고, 화면이 흔들리고, 바닥이 번쩍임
function groundImpact(w){const n=w.node,W=n.offsetWidth,H=n.offsetHeight,x=w.x,y=w.y??0;const splat=document.createElement('div');splat.className='word splat';splat.textContent=w.en;splat.style.left=x+'px';splat.style.top=y+'px';splat.style.width=W+'px';els.layer.appendChild(splat);setTimeout(()=>splat.remove(),420);impactAt(x,y+H,W)}
// 바닥에 부딪힌 자리에서 파편이 튀고, 화면이 흔들리고, 바닥이 번쩍임
function impactAt(x,bottom,W){const colors=['#ff5171','#ffd84d','#57d7d9','#fff7dc'];for(let k=0;k<10;k++){const s=document.createElement('i');s.className='spark';const a=Math.PI*(1.05+Math.random()*.9),d=40+Math.random()*60;s.style.left=(x+W*(.15+Math.random()*.7))+'px';s.style.top=bottom+'px';s.style.setProperty('--dx',Math.cos(a)*d+'px');s.style.setProperty('--dy',Math.sin(a)*d+'px');s.style.background=colors[k%colors.length];els.layer.appendChild(s);setTimeout(()=>s.remove(),520)}els.field.classList.remove('ground-hit');void els.field.offsetWidth;els.field.classList.add('ground-hit')}
// 틀린 답: 떨어지는 단어 중 하나에 금이 감. 3번 금이 가면 파괴
const CRACK_LIMIT=3;
function crack(w){w.cracks=(w.cracks||0)+1;if(w.cracks>=CRACK_LIMIT){shatter(w);return}w.node.classList.remove('crack-1','crack-2','cracking');void w.node.offsetWidth;w.node.classList.add('crack-'+w.cracks,'cracking');flash(`${w.en}에 금이 갔어요 ${w.cracks}/${CRACK_LIMIT}`,'#ffd84d')}
// 파괴: 카드가 세 조각으로 쪼개져 바닥으로 떨어지고, 부딪히면 놓친 단어처럼 위험 게이지 상승
function shatter(w){const i=state.active.indexOf(w);if(i<0)return;state.active.splice(i,1);const n=w.node,W=n.offsetWidth,H=n.offsetHeight,x=w.x,y=w.y??TOP;const groundY=els.field.clientHeight-els.ground.offsetHeight-state.groundRise;const drop=Math.max(0,groundY-H-y);const fallMs=Math.min(420,180+drop*.6);const cuts=['polygon(0 0,38% 0,30% 55%,42% 100%,0 100%)','polygon(38% 0,70% 0,62% 45%,72% 100%,42% 100%,30% 55%)','polygon(70% 0,100% 0,100% 100%,72% 100%,62% 45%)'];cuts.forEach((cp,k)=>{const sh=n.cloneNode(true);sh.className='word shard crack-2';sh.style.transform='none';sh.style.left=x+'px';sh.style.top=y+'px';sh.style.width=W+'px';sh.style.clipPath=cp;sh.style.setProperty('--dx',(k-1)*(18+Math.random()*16)+'px');sh.style.setProperty('--dy',drop+'px');sh.style.setProperty('--rot',(k-1)*(14+Math.random()*16)+'deg');sh.style.setProperty('--fall',fallMs+'ms');els.layer.appendChild(sh);setTimeout(()=>sh.remove(),620)});n.remove();flash(`${w.en} 파괴! = ${w.answers[0]}`,'#ff5171');navigator.vibrate?.([30,20,30]);setTimeout(()=>{if(!state?.running)return;impactAt(x,groundY,W);state.missed.push(w);addPressure(34);navigator.vibrate?.([60,25,90]);updateHud()},fallMs)}
function flash(text,color){els.feedback.textContent=text;els.feedback.style.color=color;els.feedback.classList.remove('show');void els.feedback.offsetWidth;els.feedback.classList.add('show')}
function updateHud(){els.score.textContent=state.score.toLocaleString();els.combo.textContent=state.combo;els.level.textContent=state.level;updateGauge()}
function pause(){if(!state?.running)return;state.paused=true;els.modal.classList.add('open');els.input.blur()}
function resume(){state.paused=false;lastTime=performance.now();els.modal.classList.remove('open');els.input.focus()}
function end(){if(!state?.running)return;state.running=false;els.input.blur();cancelAnimationFrame(raf);els.modal.classList.remove('open');const best=Math.max(Number(localStorage.getItem('wordRainBest')||0),state.score);localStorage.setItem('wordRainBest',best);$('#finalScore').textContent=state.score.toLocaleString();$('#correctCount').textContent=state.correct;$('#maxCombo').textContent=state.maxCombo;$('#missCount').textContent=state.missed.length;$('#bestStart').textContent=best.toLocaleString();els.resultBadge.textContent=`${DIFFICULTY[selectedMode].label} · LEVEL ${state.level}`;const unique=[...new Map(state.missed.map(w=>[w.en,w])).values()];state.reviewWords=unique;$('#review').innerHTML=unique.length?'<p style="background:transparent;font-weight:900">틀린 단어 전체 복습</p>'+unique.map(w=>`<p><b>${w.en}</b> &nbsp; ${w.answers.join(', ')}</p>`).join(''):'<p>놓친 단어가 없어요. 완벽해요! 🎉</p>';els.save.textContent='결과 이미지 저장 ↓';show('resultScreen')}
function roundRect(ctx,x,y,w,h,r,fill){ctx.beginPath();if(ctx.roundRect)ctx.roundRect(x,y,w,h,r);else ctx.rect(x,y,w,h);ctx.fillStyle=fill;ctx.fill()}
async function saveResultImage(){if(!state)return;const words=state.reviewWords||[];const width=1080,height=Math.max(1180,890+words.length*94);const c=document.createElement('canvas');c.width=width;c.height=height;const x=c.getContext('2d'),g=x.createLinearGradient(0,0,width,height);g.addColorStop(0,'#fff7e8');g.addColorStop(1,'#dff3eb');x.fillStyle=g;x.fillRect(0,0,width,height);x.textAlign='center';x.fillStyle='#ff7557';x.font='900 34px system-ui,sans-serif';x.fillText('하루 3분, 손끝으로 외우기',540,100);x.fillStyle='#17324d';x.font='1000 92px system-ui,sans-serif';x.fillText('단어비',540,215);roundRect(x,140,280,800,250,54,'#ffffff');x.fillStyle='#82909b';x.font='800 28px system-ui,sans-serif';x.fillText('TODAY SCORE',540,350);x.fillStyle='#17324d';x.font='1000 112px system-ui,sans-serif';x.fillText(state.score.toLocaleString(),540,475);[['맞힌 단어',state.correct],['최고 콤보',state.maxCombo],['놓친 단어',state.missed.length]].forEach(([label,value],i)=>{const cx=270+i*270;x.fillStyle='#82909b';x.font='700 25px system-ui,sans-serif';x.fillText(label,cx,610);x.fillStyle=i===2?'#ef5b61':'#17324d';x.font='1000 52px system-ui,sans-serif';x.fillText(value,cx,675)});x.textAlign='left';x.fillStyle='#17324d';x.font='1000 38px system-ui,sans-serif';x.fillText(words.length?'틀린 단어 복습':'완벽해요!',110,770);if(words.length){words.forEach((w,i)=>{const y=810+i*94;roundRect(x,95,y,890,74,22,'#ffffff');x.fillStyle='#ff7557';x.font='900 31px system-ui,sans-serif';x.fillText(w.en,130,y+48);x.fillStyle='#536677';x.font='700 29px system-ui,sans-serif';x.fillText(w.answers.join(', '),500,y+48)})}else{x.textAlign='center';x.fillStyle='#536677';x.font='700 31px system-ui,sans-serif';x.fillText('놓친 단어가 하나도 없어요!',540,860)}x.textAlign='center';x.fillStyle='#82909b';x.font='700 23px system-ui,sans-serif';x.fillText('WORD RAIN · 나의 영단어 기록',540,height-55);if(!navigator.canShare&&(IN_APP||matchMedia('(pointer:coarse)').matches)){showImagePreview(c.toDataURL('image/png'));return}const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));const file=new File([blob],`단어비-결과-${new Date().toISOString().slice(0,10)}.png`,{type:'image/png'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'단어비 학습 결과'});els.save.textContent='저장 완료 ✓';return}catch(e){if(e.name==='AbortError')return}}
// 카카오톡 같은 앱 안 브라우저나 모바일에서는 다운로드가 막혀 있어서, 이미지를 화면에 띄우고 길게 눌러 저장하게 함
if(IN_APP||matchMedia('(pointer:coarse)').matches){showImagePreview(c.toDataURL('image/png'));return}
const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=file.name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);els.save.textContent='저장 완료 ✓'}
// 앱 안 브라우저 구분 (카카오톡, 네이버, 인스타그램, 페이스북, 라인, 밴드, 다음, 에브리타임)
const UA=navigator.userAgent,IN_APP=/KAKAOTALK|NAVER\(inapp|Instagram|FBAN|FBAV|Line\/|BAND\/|DaumApps|everytimeApp/i.test(UA);
function externalBrowserUrl(){const url=location.href;if(/KAKAOTALK/i.test(UA))return'kakaotalk://web/openExternal?url='+encodeURIComponent(url);if(/Line\//i.test(UA))return url+(url.includes('?')?'&':'?')+'openExternalBrowser=1';return null}
function showImagePreview(src){document.querySelector('.image-modal')?.remove();const m=document.createElement('div');m.className='image-modal';m.setAttribute('role','dialog');m.setAttribute('aria-modal','true');const box=document.createElement('div');const tip=document.createElement('p');tip.className='image-tip';tip.textContent='이미지를 길게 눌러서 저장하세요';const img=document.createElement('img');img.src=src;img.alt='단어비 결과 이미지';box.append(tip,img);const ext=externalBrowserUrl();if(ext){const b=document.createElement('a');b.className='primary ext-btn';b.href=ext;b.textContent='저장이 안 되면 다른 브라우저로 열기';box.appendChild(b)}const close=document.createElement('button');close.className='text-btn';close.textContent='닫기';close.onclick=()=>m.remove();box.appendChild(close);m.appendChild(box);m.onclick=e=>{if(e.target===m)m.remove()};$('.app').appendChild(m);els.save.textContent='결과 이미지 저장 ↓'}
els.start.onclick=start;els.retry.onclick=start;els.save.onclick=saveResultImage;els.home.onclick=()=>{show('startScreen');$('#bestStart').textContent=Number(localStorage.getItem('wordRainBest')||0).toLocaleString()};els.pause.onclick=pause;els.resume.onclick=resume;els.quit.onclick=end;els.form.onsubmit=answer;document.addEventListener('visibilitychange',()=>{if(document.hidden&&state?.running&&!state.paused)pause()});$('#bestStart').textContent=Number(localStorage.getItem('wordRainBest')||0).toLocaleString();
// 모바일 키보드: 실제로 보이는 영역(visualViewport)에 맞춰 화면 높이와 위치를 맞추고, 키보드가 열려 있으면 작은 화면 모드(kb-open)로 전환
function syncViewport(){const vv=window.visualViewport,root=document.documentElement;const h=Math.round(vv?.height||window.innerHeight);root.style.setProperty('--app-height',`${h}px`);root.style.setProperty('--app-top',`${Math.round(vv?.offsetTop||0)}px`);const typing=document.activeElement?.tagName==='INPUT'&&matchMedia('(pointer:coarse)').matches;root.classList.toggle('kb-open',(!!vv&&vv.height<window.innerHeight*.8)||typing)}
window.visualViewport?.addEventListener('resize',syncViewport);window.visualViewport?.addEventListener('scroll',syncViewport);window.addEventListener('resize',syncViewport);document.addEventListener('focusin',()=>setTimeout(syncViewport,50));document.addEventListener('focusout',()=>setTimeout(syncViewport,50));syncViewport();
// 가로 화면 막기: 터치 기기에서 가로로 돌리면 안내를 띄우고 게임을 멈춤.
// 키보드 때문에 화면이 가로로 길어지는 경우와 헷갈리지 않도록 화면 크기가 아니라 기기 방향으로 판단
function isLandscape(){if(!matchMedia('(pointer:coarse)').matches)return false;const t=screen.orientation?.type;if(t)return t.startsWith('landscape');if(typeof window.orientation==='number')return Math.abs(window.orientation)===90;return screen.width>screen.height}
function checkOrientation(){const land=isLandscape();document.documentElement.classList.toggle('landscape',land);if(land&&state?.running&&!state.paused&&!state.ending)pause()}
screen.orientation?.addEventListener?.('change',checkOrientation);window.addEventListener('orientationchange',checkOrientation);window.addEventListener('resize',checkOrientation);checkOrientation();
function lockPortrait(){try{screen.orientation?.lock?.('portrait').catch(()=>{})}catch(e){}}
$('#vocabCount').textContent=getPool().length;document.querySelectorAll('.mode-chip').forEach(btn=>btn.onclick=()=>{selectedMode=btn.dataset.mode;document.querySelectorAll('.mode-chip').forEach(b=>b.classList.toggle('active',b===btn));$('#vocabCount').textContent=getPool().length});
// 게임 중에는 키보드가 계속 켜져 있게: 입력창 선택이 풀리지 않도록 막고, 풀리면 다음 터치 때 바로 되돌림
// (브라우저는 사용자가 터치한 순간에만 키보드를 띄울 수 있어서, 터치 이벤트 안에서 다시 선택함)
function typingActive(){return !!state?.running&&!state.paused&&!state.ending&&$('#gameScreen').classList.contains('active')}
function keepTyping(){if(typingActive()&&document.activeElement!==els.input)els.input.focus({preventScroll:true})}
const answerBtn=$('#answerBtn');
// ↵ 버튼: 누를 때 선택이 버튼으로 넘어가지 않게 하고 직접 제출
answerBtn.addEventListener('mousedown',e=>e.preventDefault());
answerBtn.addEventListener('touchend',e=>{e.preventDefault();if(els.form.requestSubmit)els.form.requestSubmit();else answer(new Event('submit'))});
// 게임 화면의 빈 곳이나 단어를 눌러도 입력창 선택 유지 (버튼은 원래대로 동작)
const gameScreen=$('#gameScreen');
gameScreen.addEventListener('mousedown',e=>{if(typingActive()&&!e.target.closest('button,input'))e.preventDefault()});
gameScreen.addEventListener('touchend',e=>{if(typingActive()&&!e.target.closest('button,input')){e.preventDefault();keepTyping()}});
